const crypto=require('node:crypto');const A=require('../server-data/accounts.cjs');
module.exports=async(req,res)=>{try{A.guard(req,res);const query=new URL(req.url,'https://'+req.headers.host).searchParams;if(query.get('step')==='callback'){const verifier=A.cookies(req).maq_verifier,code=query.get('code');if(!verifier||!code)throw Error('No se pudo validar el ingreso con Google. Volvé a intentar.');const d=await A.api('/auth/v1/token?grant_type=pkce',{method:'POST',service:false,body:{auth_code:code,code_verifier:verifier}});A.saveSession(res,d);A.setCookies(res,[A.cookie('maq_verifier','',0)]);res.setHeader('Location',A.APP+'/#profesor');return res.status(302).end()}const verifier=crypto.randomBytes(48).toString('base64url');const challenge=crypto.createHash('sha256').update(verifier).digest('base64url');A.setCookies(res,[A.cookie('maq_verifier',verifier,600)]);const url=new URL(A.URL+'/auth/v1/authorize');url.searchParams.set('provider','google');url.searchParams.set('redirect_to',A.APP+'/api/oauth?step=callback');url.searchParams.set('code_challenge',challenge);url.searchParams.set('code_challenge_method','s256');res.setHeader('Location',url.toString());return res.status(302).end()}catch(e){res.setHeader('Location',A.APP+'/?login_error='+encodeURIComponent('No se pudo completar el ingreso con Google. Revisá el proveedor y volvé a intentar.')+'#cuenta');return res.status(302).end()}};
